static lstr L9048 = {-1, 2990, "// std/async: the functions of task handles (SPEC.md section 8, D109).\012//\012// An Async<T> is the handle of a task; the type is builtin and needs no\012// import. The handle functions go through the primitives of\012// std/internal/async; all and race are async blocks, which the stage 1\012// compiler builds (the committed seed never compiles this module).\012\012import * as Arrays from \"std/array\"\012import * as Ranges from \"std/range\"\012import * as Tasks from \"std/internal/async\"\012\012// The error of every suspending std function.\012export enum AsyncError {\012  Cancelled\012  Failed(message: string)\012}\012\012// Lets the task run with nobody waiting. The task keeps running to its end, or\012// until the program exits.\012export function detach<T>(_handle: Async<T>) {}\012\012// A handle that finishes once no other task of the loop can run: none is\012// ready, sleeping or waiting on I/O, counting tasks started while it waits.\012// Idle handles finish one at a time, oldest first. In a cancelled task it\012// finishes at once.\012export function idle(): Async<void> uses alloc {\012  return Tasks.idle()\012}\012\012// Runs callback with the value when the task finishes, or on the next loop\012// turn if it has. A cancelled task drops the callback without running it. For\012// an Async<void> the callback takes no argument.\012export function then<T, effect E>(\012  handle: Async<T>,\012  escaping callback: (value: T) => void uses E\012) uses E, alloc {\012  // The runtime calls this only for a task that finished without a cancel.\012  Tasks.then(handle, (finished: Async<T>) => callback(Tasks.value(finished)))\012}\012\012// The value once the task has finished; None before that and after a cancel.\012export function peek<T>(handle: Async<T>): Option<T> uses alloc {\012  if (Tasks.finished(handle)) {\012    return Some(Tasks.value(handle))\012  }\012  return None\012}\012\012// Cancels the task: its then callbacks are dropped, peek gives None, a sleep\012// or Async.idle it waits in ends at once, and its suspending std calls give\012// Err(AsyncError.Cancelled). A finished task is left as it is.\012export function cancel<T>(handle: Async<T>) {\012  Tasks.cancel(handle)\012}\012\012// Every value, in the order of the handles, once each task has finished. A\012// cancel of the result does not reach the handles.\012export function all<T>(handles: Array<Async<T>>): Async<Array<T>> from handles uses alloc {\012  return async {\012    Tasks.keepInputs()\012    let values: Array<T> = []\012    for (const handle of Arrays.values(handles)) {\012      Arrays.push(mutable values, await handle)\012    }\012    return values\012  }\012}\012\012// The value of the first task to finish, or None for no handles. The other\012// tasks keep running.\012export function race<T>(handles: Array<Async<T>>): Async<Option<T>> from handles uses alloc {\012  return async {\012    if (Arrays.length(handles) == 0) {\012      return None\012    }\012    const winner = Tasks.winner()\012    for (const index of Ranges.between(0, Arrays.length(handles))) {\012      Tasks.watch(winner, handles[index], index)\012    }\012    const first = await winner\012    return Some(await handles[first])\012  }\012}\012"};
static lstr L9049 = {-1, 14, "std/async/file"};
static lstr L9050 = {-1, 2626, "// std/async/file: whole-file reads and writes for async code (SPEC.md section 8, D109).\012//\012// kqueue and epoll do not wait on regular files, so each call reads or writes\012// in one blocking step, as std/fs does, then lets the other ready tasks run\012// once before it returns. A cancelled task's call gives\012// Err(AsyncError.Cancelled) before it touches the file.\012\012import * as Fs from \"std/fs\"\012import * as Tasks from \"std/internal/async\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012// The text of the file at path.\012export async function readText(path: string): Result<string, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.readText(path)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(text) => Ok(text), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// The bytes of the file at path.\012export async function readBytes(path: string): Result<bytes, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.readBytes(path)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(data) => Ok(data), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// Writes text to the file at path, replacing it, and gives the bytes written.\012export async function writeText(\012  path: string,\012  text: string,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.writeText(path, text)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(count) => Ok(count), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// Writes data to the file at path, replacing it, and gives the bytes written.\012export async function writeBytes(\012  path: string,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.writeBytes(path, data)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(count) => Ok(count), Err(message) => Err(AsyncError.Failed(message)) }\012}\012"};
static lstr L9051 = {-1, 13, "std/async/net"};
static lstr L9052 = {-1, 5216, "// std/async/net: TCP sockets on the loop of the thread (SPEC.md section 8, D109).\012//\012// listen and localPort do not suspend. accept, connect, read and write wait in\012// the loop until the socket is ready, so the other tasks run meanwhile. A\012// Listener or a Connection is a handle: copies share the socket, and it\012// closes when the last copy is dropped. host is a numeric IPv4 or IPv6\012// address; there is no name lookup.\012\012import * as Bytes from \"std/bytes\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012export opaque struct Listener {\012  handle: Handle\012}\012\012export opaque struct Connection {\012  handle: Handle\012}\012\012function failWith(code: int): AsyncError uses alloc {\012  return AsyncError.Failed(Handles.message(code))\012}\012\012// The error of a wait that ended with ready: None when the socket is ready.\012// Each suspending function waits itself, never through a helper task, so a\012// cancel of the task that awaits it reaches the wait. One task at a time may\012// wait in each direction; busy names what the other task already does.\012function checkWait(ready: int, busy: string): Option<AsyncError> uses alloc {\012  if (ready < 0) {\012    return Some(AsyncError.Cancelled)\012  }\012  if (Handles.busy(ready)) {\012    return Some(AsyncError.Failed(`another task is already ${busy}`))\012  }\012  if (ready > 0) {\012    return Some(failWith(ready))\012  }\012  return None\012}\012\012// A socket that accepts connections on host and port. Port 0 picks a free\012// port, which localPort gives.\012export function listen(host: string, port: int): Result<Listener, AsyncError> uses io, alloc {\012  const handle = Handles.listen(host, port)\012  const code = Handles.error()\012  if (code != 0) {\012    return Err(failWith(code))\012  }\012  return Ok(Listener { handle: handle })\012}\012\012// The port the listener is bound to.\012export function localPort(listener: Listener): int uses io {\012  return Handles.localPort(listener.handle)\012}\012\012// The next connection to the listener.\012export async function accept(listener: Listener): Result<Connection, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const handle = Handles.accept(listener.handle)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(Connection { handle: handle })\012    }\012    // A connection that went before it was taken leaves the others to accept.\012    if (!Handles.acceptAgain(code)) {\012      if (!Handles.retry(code)) {\012        return Err(failWith(code))\012      }\012      const problem = checkWait(\012        await Handles.wait(listener.handle, false),\012        \"accepting on this listener\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012  return Err(AsyncError.Cancelled)\012}\012\012// A connection to host and port.\012export async function connect(\012  host: string,\012  port: int,\012): Result<Connection, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const handle = Handles.connect(host, port)\012  const code = Handles.error()\012  if (code == 0) {\012    return Ok(Connection { handle: handle })\012  }\012  if (!Handles.pending(code)) {\012    return Err(failWith(code))\012  }\012  const problem = checkWait(await Handles.wait(handle, true), \"connecting this socket\")\012  if (problem is Some(error)) {\012    return Err(error)\012  }\012  const result = Handles.connected(handle)\012  if (result != 0) {\012    return Err(failWith(result))\012  }\012  return Ok(Connection { handle: handle })\012}\012\012// Up to maxBytes bytes from the connection, at most 64 KiB, once some are\012// there. Empty bytes mean the peer has closed its side; a maxBytes of zero or\012// less gives empty bytes at once.\012export async function read(\012  connection: Connection,\012  maxBytes: int,\012): Result<bytes, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const data = Handles.read(connection.handle, maxBytes)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(data)\012    }\012    if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    }\012    const problem = checkWait(\012      await Handles.wait(connection.handle, false),\012      \"reading this connection\",\012    )\012    if (problem is Some(error)) {\012      return Err(error)\012    }\012  }\012  return Err(AsyncError.Cancelled)\012}\012\012// Writes every byte of data and gives the count. A cancel while it waits\012// ends it with Err(AsyncError.Cancelled), whatever part was sent.\012export async function write(\012  connection: Connection,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  let sent = 0\012  const total = Bytes.length(data)\012  // A wait that a cancel ends gives -1, so the loop needs no second check.\012  while (sent < total) {\012    const count = Handles.write(connection.handle, data, sent)\012    const code = Handles.error()\012    if (code == 0) {\012      sent += count\012    } else if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    } else {\012      const problem = checkWait(\012        await Handles.wait(connection.handle, true),\012        \"writing this connection\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012  return Ok(sent)\012}\012"};
static lstr L9053 = {-1, 14, "std/async/time"};
static lstr L9054 = {-1, 787, "// std/async/time: sleep on the loop of the thread (SPEC.md section 8, D109).\012//\012// sleep suspends the running task until the duration has passed; the other\012// tasks of the loop run meanwhile. Time.sleep of std/time blocks the loop.\012\012import * as Tasks from \"std/internal/async\"\012import * as Time from \"std/time\"\012import { Duration } from \"std/time\"\012import { AsyncError } from \"std/async\"\012\012// Waits for duration and gives the time slept, or Err(AsyncError.Cancelled)\012// at once when the task is cancelled, before or while it waits.\012export async function sleep(duration: Duration): Result<Duration, AsyncError> uses io, alloc {\012  const slept = await Tasks.sleep(Time.asNanoseconds(duration))\012  if (slept < 0) {\012    return Err(AsyncError.Cancelled)\012  }\012  return Ok(Time.nanoseconds(slept))\012}\012"};
static lstr L9055 = {-1, 9, "std/build"};
static lstr L9056 = {-1, 1133, "// std/build: the target a program is built for. The compiler sets os, arch and\012// debug for each build; the values written here are replaced. An `if` that\012// tests only these constants keeps one branch in the output.\012\012import * as Host from \"std/internal/host\"\012\012export enum Os derives Show, Equatable {\012  MacOS\012  Linux\012  Windows\012}\012\012export enum Arch derives Show, Equatable {\012  Arm64\012  X86_64\012}\012\012export const os: Os = Os.Linux\012export const arch: Arch = Arch.X86_64\012export const debug: bool = true\012\012export struct Target {\012  os: Os\012  arch: Arch\012}\012\012export function hostTarget(): Option<Target> {\012  const hostOs = Host.os()\012  const hostArch = Host.arch()\012  // The C compiler's predefined macros give the codes; 0 is a machine with no variant here.\012  if (hostOs == 0 || hostArch == 0) {\012    return None\012  }\012  if (hostOs == 1 && hostArch == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.Arm64 })\012  }\012  if (hostOs == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.X86_64 })\012  }\012  if (hostArch == 1) {\012    return Some(Target { os: Os.Linux, arch: Arch.Arm64 })\012  }\012  return Some(Target { os: Os.Linux, arch: Arch.X86_64 })\012}\012"};
static lstr L9057 = {-1, 8, "std/cell"};
static lstr L9058 = {-1, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
static lstr L9059 = {-1, 13, "std/coroutine"};
static lstr L9060 = {-1, 1043, "// std/coroutine: Co.resume runs a generator or a coroutine to its next yield.\012//\012// The compiler turns `Co.resume(mutable g)` into resumeGenerator and\012// `Co.resume(mutable g, input)` into resumeCoroutine, by argument count.\012\012import * as Internal from \"std/internal/coroutine\"\012\012export enum Step<Out> derives Show, Equatable {\012  Yielded(value: Out)\012  Done\012  Panicked(message: string)\012}\012\012export function resumeGenerator<T, effect E>(\012  mutable g: Generator<T> uses E\012): Step<T> uses E, alloc {\012  return readStep(Internal.next(mutable g))\012}\012\012export function resumeCoroutine<In, Out, effect E>(\012  mutable g: Coroutine<In, Out> uses E,\012  input: In,\012): Step<Out> uses E, alloc {\012  return readStep(Internal.resume(mutable g, input))\012}\012\012// readStep reads the outcome of one resume: a value, the end, or a panic.\012function readStep<T>(next: Option<T>): Step<T> from next uses alloc {\012  if (next is Some(value)) {\012    return Step.Yielded(value)\012  }\012  if (Internal.panicked()) {\012    return Step.Panicked(Internal.panicMessage())\012  }\012  return Step.Done\012}\012"};
static lstr L9061 = {-1, 11, "std/cstring"};
static lstr L9062 = {-1, 1182, "// std/cstring: CString, a string with no zero byte, which C reads as a zero-terminated string.\012//\012// Pass `CStrings.pointer(text)` to a C function that takes `char*`; the pointer is valid while\012// the CString is. `CStrings.read` copies a zero-terminated string that C returns.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Ptr from \"std/ptr\"\012import * as Text from \"std/internal/cstring\"\012\012export opaque struct CString {\012  text: string\012}\012\012export function from(text: string): Option<CString> {\012  // C would stop at a zero byte, so a string that holds one has no CString.\012  const length = Str.length(text)\012  for (let index = 0; index < length; index++) {\012    if (Str.byteAt(text, index) == 0) {\012      return None\012    }\012  }\012  return Some(CString { text: text })\012}\012\012export function toString(value: CString): string from value {\012  return value.text\012}\012\012export function pointer(value: CString): Ptr<u8> {\012  return Text.pointer(value.text)\012}\012\012export function read(address: Ptr<u8>): Result<string, string> uses alloc, unsafe {\012  let copied: Result<string, string> = Err(\"\")\012  unsafe {\012    copied = Bytes.toString(Text.read(address))\012  }\012  return copied\012}\012"};
static lstr L9063 = {-1, 13, "std/ext/array"};
static lstr L9064 = {-1, 833, "// std/array: helpers over Array. The functions that need the compiler are built in.\012\012import * as Arrays from \"std/array\"\012\012export function map<T, U, effect E>(\012  items: Array<T>,\012  change: (value: T) => U uses E\012): Array<U> uses alloc, E {\012  let result: Array<U> = Arrays.withCapacity(Arrays.length(items))\012  for (const item of items) {\012    Arrays.push(mutable result, change(item))\012  }\012  return result\012}\012\012export function slice<T>(items: Array<T>, start: int, finish: int): Option<Array<T>> uses alloc {\012  // A range outside the array has no slice.\012  if (start < 0 || finish > Arrays.length(items) || start > finish) {\012    return None\012  }\012  let result: Array<T> = Arrays.withCapacity(finish - start)\012  for (let index = start; index < finish; index++) {\012    Arrays.push(mutable result, copy(items[index]))\012  }\012  return Some(result)\012}\012"};
static lstr L9065 = {-1, 13, "std/ext/float"};
static lstr L9066 = {-1, 117, "// std/float: constants of f64. The functions are built into the compiler.\012\012export const PI: f64 = 3.141592653589793\012"};
static lstr L9067 = {-1, 11, "std/ext/int"};
static lstr L9068 = {-1, 915, "// std/int: ordering and division of int. The rest of the functions are built into the compiler.\012\012export function compare(first: int, second: int): Ordering {\012  if (first < second) {\012    return Ordering.Less\012  }\012  if (first > second) {\012    return Ordering.Greater\012  }\012  return Ordering.Equal\012}\012\012export function divmod(dividend: int, divisor: int): Option<#[int, int]> {\012  // A zero divisor has no quotient.\012  if (divisor == 0) {\012    return None\012  }\012  return Some(#[dividend / divisor, dividend % divisor])\012}\012\012export function floorDiv(dividend: int, divisor: int): Option<int> {\012  if (divisor == 0) {\012    return None\012  }\012  const quotient = dividend / divisor\012  const remainder = dividend % divisor\012  // Division truncates toward zero; step down when the signs differ and the division is inexact.\012  if (remainder != 0 && (remainder < 0) != (divisor < 0)) {\012    return Some(quotient - 1)\012  }\012  return Some(quotient)\012}\012"};
static lstr L9069 = {-1, 14, "std/ext/string"};
static lstr L9070 = {-1, 231, "// std/string: searching. The rest of the functions are built into the compiler.\012\012import * as Str from \"std/string\"\012\012export function find(text: string, needle: string): Option<int> uses alloc {\012  return Str.indexOf(text, needle)\012}\012"};
static lstr L9071 = {-1, 14, "std/fixedarray"};
static lstr L9072 = {-1, 425, "// std/fixedarray: helpers over FixedArray. An index written as values[i] must be\012// proven in range; get checks the index and returns None outside it.\012\012export function get<T, const N: int>(values: FixedArray<T, N>, index: int): Option<T> from values {\012  if (index >= 0 && index < N) {\012    return Some(values[index])\012  }\012  return None\012}\012\012export function length<T, const N: int>(_values: FixedArray<T, N>): int {\012  return N\012}\012"};
static lstr L9073 = {-1, 8, "std/hash"};
static lstr L9074 = {-1, 670, "// std/hash: hashing. `of` is the hash of a Hashable value and may change between builds.\012// `fnv1a` is FNV-1a 64 over the UTF-8 bytes of a string and never changes.\012\012import * as Str from \"std/string\"\012import * as U64 from \"std/u64\"\012import * as Ranges from \"std/range\"\012\012const FNV_OFFSET: u64 = 14695981039346656037\012const FNV_PRIME: u64 = 1099511628211\012\012export function of<T: Hashable>(value: T): int {\012  return Hashable.hash(value)\012}\012\012export function fnv1a(text: string): u64 {\012  let state = FNV_OFFSET\012  const length = Str.length(text)\012  for (const index of Ranges.upTo(length)) {\012    state = (state ^ U64.wrap(Str.byteAt(text, index))) * FNV_PRIME\012  }\012  return state\012}\012"};
static lstr L9075 = {-1, 8, "std/json"};
static lstr L9076 = {-1, 16470, "// std/json: parse and stringify JSON text (RFC 8259) as a Value of std/shape.\012\012import * as Str from \"std/string\"\012import * as Int from \"std/int\"\012import * as Char from \"std/char\"\012import * as Float from \"std/float\"\012import * as Arrays from \"std/array\"\012import * as Maps from \"std/map\"\012import * as FloatText from \"std/internal/float\"\012import { Value, Shape } from \"std/shape\"\012\012// Containers nested deeper than this are an error, so the recursion is bounded.\012const MAX_DEPTH = 512\012\012struct Parser {\012  text: string\012  length: int\012  position: int\012}\012\012// parse reads one JSON value. Errors read `<line>:<column>: <reason>`.\012export function parse(text: string): Result<Value, string> uses alloc {\012  let parser = Parser { text: text, length: Str.length(text), position: 0 }\012  skipSpace(mutable parser)\012  const value = parseValue(mutable parser, 0)\012  if (value is Err(message)) {\012    return Err(message)\012  }\012  skipSpace(mutable parser)\012  if (parser.position < parser.length) {\012    return fail(parser, parser.position, \"unexpected character after the value\")\012  }\012  return Ok(value.value)\012}\012\012// stringify writes a value as compact JSON text. A non-finite Float is null.\012export function stringify(value: Value): string uses alloc {\012  let builder = Str.builder()\012  writeValue(mutable builder, value)\012  return Str.build(builder)\012}\012\012// fail builds the error for the byte at position, as line:column: reason.\012function fail<T>(parser: Parser, position: int, reason: string): Result<T, string> uses alloc {\012  let line = 1\012  let column = 1\012  let index = 0\012  while (index < position && index < parser.length) {\012    const byte = Str.byteAt(parser.text, index)\012    if (byte == 10) {\012      line += 1\012      column = 1\012    } else if (byte < 128 || byte >= 192) {\012      column += 1\012    }\012    index += 1\012  }\012  if (position >= parser.length) {\012    return Err(`${Int.toString(line)}:${Int.toString(column)}: unexpected end of input`)\012  }\012  return Err(`${Int.toString(line)}:${Int.toString(column)}: ${reason}`)\012}\012\012function cutText(text: string, start: int, end: int): string uses alloc {\012  if (Str.slice(text, start, end) is Some(piece)) {\012    return piece\012  }\012  panic(\"cutText: the range is outside the text\")\012}\012\012function skipSpace(mutable parser: Parser) {\012  while (parser.position < parser.length) {\012    const byte = Str.byteAt(parser.text, parser.position)\012    if (byte != 32 && byte != 9 && byte != 10 && byte != 13) {\012      return\012    }\012    parser.position += 1\012  }\012}\012\012function parseValue(mutable parser: Parser, depth: int): Result<Value, string> uses alloc {\012  if (parser.position >= parser.length) {\012    return fail(parser, parser.position, \"expected a value\")\012  }\012  const byte = Str.byteAt(parser.text, parser.position)\012  if (byte == 123) {\012    return parseRecord(mutable parser, depth + 1)\012  }\012  if (byte == 91) {\012    return parseList(mutable parser, depth + 1)\012  }\012  if (byte == 34) {\012    const text = parseString(mutable parser)\012    if (text is Err(message)) {\012      return Err(message)\012    }\012    return Ok(Value.Text(text.value))\012  }\012  if (byte == 45 || (byte >= 48 && byte <= 57)) {\012    return parseNumber(mutable parser)\012  }\012  if (readWord(mutable parser, \"true\")) {\012    return Ok(Value.Bool(true))\012  }\012  if (readWord(mutable parser, \"false\")) {\012    return Ok(Value.Bool(false))\012  }\012  if (readWord(mutable parser, \"null\")) {\012    return Ok(Value.Null)\012  }\012  return fail(parser, parser.position, \"expected a value\")\012}\012\012// readWord consumes word when the text continues with it. It compares bytes,\012// because a slice of the text could end inside a multibyte character.\012function readWord(mutable parser: Parser, word: string): bool {\012  const count = Str.length(word)\012  if (parser.position + count > parser.length) {\012    return false\012  }\012  let index = 0\012  while (index < count) {\012    if (Str.byteAt(parser.text, parser.position + index) != Str.byteAt(word, index)) {\012      return false\012    }\012    index += 1\012  }\012  parser.position += count\012  return true\012}\012\012function parseList(mutable parser: Parser, depth: int): Result<Value, string> uses alloc {\012  if (depth > MAX_DEPTH) {\012    return fail(parser, parser.position, \"nesting is deeper than 512\")\012  }\012  // Skip the [.\012  parser.position += 1\012  let items: Array<Value> = []\012  skipSpace(mutable parser)\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 93) {\012    parser.position += 1\012    return Ok(Value.List(items))\012  }\012  while (true) {\012    skipSpace(mutable parser)\012    const item = parseValue(mutable parser, depth)\012    if (item is Err(message)) {\012      return Err(message)\012    }\012    Arrays.push(mutable items, item.value)\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"expected , or ]\")\012    }\012    const byte = Str.byteAt(parser.text, parser.position)\012    parser.position += 1\012    if (byte == 93) {\012      return Ok(Value.List(items))\012    }\012    if (byte != 44) {\012      return fail(parser, parser.position - 1, \"expected , or ]\")\012    }\012  }\012  return fail(parser, parser.position, \"unreachable\")\012}\012\012function parseRecord(mutable parser: Parser, depth: int): Result<Value, string> uses alloc {\012  if (depth > MAX_DEPTH) {\012    return fail(parser, parser.position, \"nesting is deeper than 512\")\012  }\012  // Skip the {.\012  parser.position += 1\012  let fields: Map<string, Value> = Map {}\012  skipSpace(mutable parser)\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 125) {\012    parser.position += 1\012    return Ok(Value.Record(fields))\012  }\012  while (true) {\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length || Str.byteAt(parser.text, parser.position) != 34) {\012      return fail(parser, parser.position, \"expected a string key\")\012    }\012    const key = parseString(mutable parser)\012    if (key is Err(message)) {\012      return Err(message)\012    }\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length || Str.byteAt(parser.text, parser.position) != 58) {\012      return fail(parser, parser.position, \"expected :\")\012    }\012    parser.position += 1\012    skipSpace(mutable parser)\012    const field = parseValue(mutable parser, depth)\012    if (field is Err(message)) {\012      return Err(message)\012    }\012    // The last duplicate wins; an existing key keeps its place.\012    fields[key.value] = field.value\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"expected , or }\")\012    }\012    const byte = Str.byteAt(parser.text, parser.position)\012    parser.position += 1\012    if (byte == 125) {\012      return Ok(Value.Record(fields))\012    }\012    if (byte != 44) {\012      return fail(parser, parser.position - 1, \"expected , or }\")\012    }\012  }\012  return fail(parser, parser.position, \"unreachable\")\012}\012\012function isDigit(byte: int): bool {\012  return byte >= 48 && byte <= 57\012}\012\012// skipDigits moves past a run of digits and says how many there were.\012function skipDigits(mutable parser: Parser): int {\012  let count = 0\012  while (parser.position < parser.length && isDigit(Str.byteAt(parser.text, parser.position))) {\012    parser.position += 1\012    count += 1\012  }\012  return count\012}\012\012function parseNumber(mutable parser: Parser): Result<Value, string> uses alloc {\012  const start = parser.position\012  let isFloat = false\012  if (Str.byteAt(parser.text, parser.position) == 45) {\012    parser.position += 1\012  }\012  // Integer part: 0, or a nonzero digit and more digits.\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 48) {\012    parser.position += 1\012  } else if (skipDigits(mutable parser) == 0) {\012    return fail(parser, parser.position, \"invalid number\")\012  }\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 46) {\012    isFloat = true\012    parser.position += 1\012    if (skipDigits(mutable parser) == 0) {\012      return fail(parser, parser.position, \"invalid number\")\012    }\012  }\012  if (parser.position < parser.length) {\012    const marker = Str.byteAt(parser.text, parser.position)\012    if (marker == 101 || marker == 69) {\012      isFloat = true\012      parser.position += 1\012      if (parser.position < parser.length) {\012        const sign = Str.byteAt(parser.text, parser.position)\012        if (sign == 43 || sign == 45) {\012          parser.position += 1\012        }\012      }\012      if (skipDigits(mutable parser) == 0) {\012        return fail(parser, parser.position, \"invalid number\")\012      }\012    }\012  }\012  const digits = cutText(parser.text, start, parser.position)\012  if (!isFloat) {\012    // An integer outside int becomes a Float.\012    const whole = Int.parse(digits, 10)\012    if (whole is Ok(number)) {\012      return Ok(Value.Int(number))\012    }\012  }\012  return Ok(Value.Float(FloatText.parse(digits)))\012}\012\012// The value of a hexadecimal digit, or -1.\012function hexValue(byte: int): int {\012  if (byte >= 48 && byte <= 57) {\012    return byte - 48\012  }\012  if (byte >= 97 && byte <= 102) {\012    return byte - 87\012  }\012  if (byte >= 65 && byte <= 70) {\012    return byte - 55\012  }\012  return -1\012}\012\012// readHex4 reads the four hex digits at parser.position.\012function readHex4(mutable parser: Parser): Result<int, string> uses alloc {\012  let code = 0\012  let count = 0\012  while (count < 4) {\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"\")\012    }\012    const digit = hexValue(Str.byteAt(parser.text, parser.position))\012    if (digit < 0) {\012      return fail(parser, parser.position, \"invalid \\\\u escape\")\012    }\012    code = code * 16 + digit\012    parser.position += 1\012    count += 1\012  }\012  return Ok(code)\012}\012\012// parseString reads a string whose opening quote is at parser.position.\012function parseString(mutable parser: Parser): Result<string, string> uses alloc {\012  parser.position += 1\012  let builder = Str.builder()\012  // The start of the plain bytes not yet copied.\012  let runStart = parser.position\012  while (true) {\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"\")\012    }\012    const byte = Str.byteAt(parser.text, parser.position)\012    if (byte == 34) {\012      Str.append(mutable builder, cutText(parser.text, runStart, parser.position))\012      parser.position += 1\012      return Ok(Str.build(builder))\012    }\012    if (byte < 32) {\012      return fail(parser, parser.position, \"control character in string\")\012    }\012    if (byte != 92) {\012      parser.position += 1\012      continue\012    }\012    Str.append(mutable builder, cutText(parser.text, runStart, parser.position))\012    parser.position += 1\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"\")\012    }\012    const escape = Str.byteAt(parser.text, parser.position)\012    const escapeAt = parser.position - 1\012    parser.position += 1\012    if (escape == 117) {\012      const unit = readHex4(mutable parser)\012      if (unit is Err(message)) {\012        return Err(message)\012      }\012      const code = readCodePoint(mutable parser, unit.value, escapeAt)\012      if (code is Err(message)) {\012        return Err(message)\012      }\012      if (Char.fromCode(code.value) is Some(character)) {\012        Str.appendChar(mutable builder, character)\012      }\012    } else {\012      const simple = simpleEscape(escape)\012      if (simple == \"\") {\012        return fail(parser, escapeAt, \"invalid escape\")\012      }\012      Str.append(mutable builder, simple)\012    }\012    runStart = parser.position\012  }\012  return fail(parser, parser.position, \"unreachable\")\012}\012\012// The text for the escape letter after a backslash, or \"\".\012function simpleEscape(letter: int): string uses alloc {\012  if (letter == 34) {\012    return \"\\\"\"\012  }\012  if (letter == 92) {\012    return \"\\\\\"\012  }\012  if (letter == 47) {\012    return \"/\"\012  }\012  if (letter == 98) {\012    return controlText(8)\012  }\012  if (letter == 102) {\012    return controlText(12)\012  }\012  if (letter == 110) {\012    return \"\\n\"\012  }\012  if (letter == 114) {\012    return \"\\r\"\012  }\012  if (letter == 116) {\012    return \"\\t\"\012  }\012  return \"\"\012}\012\012function controlText(code: int): string uses alloc {\012  if (Char.fromCode(code) is Some(character)) {\012    return Str.fromChar(character)\012  }\012  return \"\"\012}\012\012// readCodePoint joins a surrogate pair; a lone surrogate is an error at escapeAt.\012function readCodePoint(\012  mutable parser: Parser,\012  unit: int,\012  escapeAt: int,\012): Result<int, string> uses alloc {\012  if (unit >= 56320 && unit <= 57343) {\012    return fail(parser, escapeAt, \"lone surrogate\")\012  }\012  if (unit < 55296 || unit > 56319) {\012    return Ok(unit)\012  }\012  // A high surrogate needs \\u and a low surrogate right after it.\012  if (!readWord(mutable parser, \"\\\\u\")) {\012    return fail(parser, escapeAt, \"lone surrogate\")\012  }\012  const low = readHex4(mutable parser)\012  if (low is Err(message)) {\012    return Err(message)\012  }\012  if (low.value < 56320 || low.value > 57343) {\012    return fail(parser, escapeAt, \"lone surrogate\")\012  }\012  return Ok(65536 + (unit - 55296) * 1024 + (low.value - 56320))\012}\012\012function writeValue(mutable builder: StringBuilder, value: Value) uses alloc {\012  match (value) {\012    Value.Null => Str.append(mutable builder, \"null\")\012    Value.Bool(flag) => {\012      if (flag) {\012        Str.append(mutable builder, \"true\")\012      } else {\012        Str.append(mutable builder, \"false\")\012      }\012    }\012    Value.Int(number) => Str.append(mutable builder, Int.toString(number))\012    Value.Float(number) => {\012      // NaN and infinities have no JSON form; JSON.stringify writes null.\012      if (number - number != 0.0) {\012        Str.append(mutable builder, \"null\")\012      } else {\012        Str.append(mutable builder, floatText(number))\012      }\012    }\012    Value.Text(text) => writeString(mutable builder, text)\012    Value.List(items) => {\012      Str.append(mutable builder, \"[\")\012      let first = true\012      for (const item of Arrays.values(items)) {\012        if (!first) {\012          Str.append(mutable builder, \",\")\012        }\012        first = false\012        writeValue(mutable builder, item)\012      }\012      Str.append(mutable builder, \"]\")\012    }\012    Value.Record(fields) => {\012      Str.append(mutable builder, \"{\")\012      let first = true\012      for (const entry of Maps.entries(fields)) {\012        const #[key, field] = entry\012        if (!first) {\012          Str.append(mutable builder, \",\")\012        }\012        first = false\012        writeString(mutable builder, key)\012        Str.append(mutable builder, \":\")\012        writeValue(mutable builder, field)\012      }\012      Str.append(mutable builder, \"}\")\012    }\012  }\012}\012\012// floatText writes a finite Float. A whole number below 1e15 reads as digits and\012// \".0\" (Float.toString would write 1e+02 for 100.0); the rest keeps its shortest text.\012function floatText(number: f64): string uses alloc {\012  if (number > -1000000000000000.0 && number < 1000000000000000.0) {\012    if (Float.truncate(number) is Some(whole)) {\012      if (Float.fromInt(whole) == number) {\012        return `${Int.toString(whole)}.0`\012      }\012    }\012  }\012  return Float.toString(number)\012}\012\012function writeString(mutable builder: StringBuilder, text: string) uses alloc {\012  Str.append(mutable builder, \"\\\"\")\012  const length = Str.length(text)\012  // The start of the bytes that need no escape and are not yet copied.\012  let runStart = 0\012  let index = 0\012  while (index < length) {\012    const byte = Str.byteAt(text, index)\012    if (byte >= 32 && byte != 34 && byte != 92) {\012      index += 1\012      continue\012    }\012    Str.append(mutable builder, cutText(text, runStart, index))\012    Str.append(mutable builder, escapeByte(byte))\012    index += 1\012    runStart = index\012  }\012  Str.append(mutable builder, cutText(text, runStart, length))\012  Str.append(mutable builder, \"\\\"\")\012}\012\012// The JSON escape for a quote, a backslash or a control character.\012function escapeByte(byte: int): string uses alloc {\012  if (byte == 34) {\012    return \"\\\\\\\"\"\012  }\012  if (byte == 92) {\012    return \"\\\\\\\\\"\012  }\012  if (byte == 10) {\012    return \"\\\\n\"\012  }\012  if (byte == 13) {\012    return \"\\\\r\"\012  }\012  if (byte == 9) {\012    return \"\\\\t\"\012  }\012  if (byte == 8) {\012    return \"\\\\b\"\012  }\012  if (byte == 12) {\012    return \"\\\\f\"\012  }\012  const hex = Int.toHex(byte)\012  if (Str.repeat(\"0\", 4 - Str.length(hex)) is Some(padding)) {\012    return `\\\\u${padding}${hex}`\012  }\012  return `\\\\u${hex}`\012}\012\012// encode writes any value that implements Shape as compact JSON text.\012export function encode<T: Shape>(value: T): string uses alloc {\012  return stringify(Shape.toValue(value))\012}\012\012// decode reads JSON text as a T: `Json.decode<User>(text)`. A parse error is\012// passed through; a shape error reads `<path>: <reason>` (see std/shape).\012export function decode<T: Shape>(text: string): Result<T, string> uses alloc {\012  const value = parse(text)\012  if (value is Err(message)) {\012    return Err(message)\012  }\012  return Shape.fromValue<T>(value.value)\012}\012"};
